def compute(vars):
    total_size = vars["v1"]
    number_of_call_centers = vars["v2"]

    if number_of_call_centers == 0:
        return None

    average_size = total_size / number_of_call_centers

    return {
        "value": average_size,
        "trace": {
            "total_size": total_size,
            "number_of_call_centers": number_of_call_centers,
            "average_size": average_size,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "square feet"
            }
        }
    }
